def max_adjacent_sum(nums):
    if len(nums) < 2:
        return 0
    max_sum = nums[0] + nums[1]
    for i in range(1, len(nums) - 1):
        current = nums[i] + nums[i + 1]
        if current > max_sum:
            max_sum = current
    return max_sum

import re

def count_word_frequency(text):
    words = re.findall(r'[A-Za-z0-9]+', text.lower())
    freq = {}
    for word in words:
        freq[word] = freq.get(word, 0) + 1
    return freq

def average_even(nums):
    total = 0
    count = 0
    for num in nums:
        if num % 2 == 0:
            total += num
            count += 1
    if count == 0:
        return 0
    return total / count

def normalize_name(full_name: str) -> str:
    parts = full_name.strip().split()
    if not parts:
        return ""
    normalized = [p.capitalize() for p in parts]
    if len(normalized) == 1:
        return normalized[0]
    return normalized[-1] + ", " + " ".join(normalized[:-1])

def max_consecutive_ones(nums: list[int]) -> int:
    max_count = 0
    current = 0
    for x in nums:
        if x == 1:
            current += 1
            max_count = max(max_count, current)
        else:
            current = 0
    return max_count

