def find_peak_element(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[mid + 1]:
            right = mid
        else:
            left = mid + 1
    return left

class Library:
    def __init__(self, copies):
        self.copies = copies.copy()

    def borrow(self, title):
        if title in self.copies and self.copies[title] > 0:
            self.copies[title] -= 1
            return True
        return False

    def return_book(self, title):
        if title in self.copies:
            self.copies[title] += 1

    def available_copies(self, title):
        return self.copies.get(title, 0)

class OrderBook:
    def __init__(self):
        self._orders = {}
        self._buy_orders = []
        self._sell_orders = []

    def add_order(self, order_id, side, price, quantity):
        if order_id in self._orders:
            self.cancel_order(order_id)
        order = {'order_id': order_id, 'price': price, 'quantity': quantity}
        self._orders[order_id] = (side, order)
        if side == 'buy':
            self._buy_orders.append(order)
            self._buy_orders.sort(key=lambda x: (-x['price'], x['order_id']))
        else:
            self._sell_orders.append(order)
            self._sell_orders.sort(key=lambda x: (x['price'], x['order_id']))

    def cancel_order(self, order_id):
        if order_id not in self._orders:
            return
        side, order = self._orders.pop(order_id)
        if side == 'buy':
            self._buy_orders.remove(order)
        else:
            self._sell_orders.remove(order)

    def get_best_buy(self):
        if not self._buy_orders:
            return None
        return self._buy_orders[0].copy()

    def get_best_sell(self):
        if not self._sell_orders:
            return None
        return self._sell_orders[0].copy()

    def get_order_count(self):
        return len(self._orders)

